const lead = $('On Qualification Request').item.json;
const rows = $('Load Lead State').all().map(i => i.json);
const rec = rows[0] || {};
const ef = rec.fields || rec;
const known = {};
for (const k of ['intent','extracted_signals','summary','score','temperature','qualification_status']) {
  const v = ef[k];
  if (v !== undefined && v !== null && v !== '') known[k] = v;
}
return [{
  json: {
    lead_id: lead.lead_id || rec.id || '',
    correlation_id: lead.correlation_id,
    idempotency_key: lead.idempotency_key,
    source: lead.source,
    name: lead.name,
    email: lead.email,
    company: lead.company,
    message: lead.message,
    consent_status: lead.consent_status,
    known_state: known,
    prompt_input: {
      name: lead.name,
      email: lead.email,
      company: lead.company,
      message: lead.message
    }
  }
}];

