const lead = $('Prepare AI Input').item.json;
const raw = $input.first().json;
const aiOut = raw.output || raw;
const threshold = 0.70;
let ok = true;
let reason = '';
let intent = '';
let confidence = NaN;
let signals = {};
let summary = '';
if (raw.error || !aiOut || typeof aiOut !== 'object') {
  ok = false; reason = 'llm_timeout_or_malformed';
} else {
  intent = aiOut.intent || '';
  confidence = Number(aiOut.intent_confidence);
  signals = aiOut.extracted_signals || {};
  summary = aiOut.summary || '';
  if (!intent || typeof confidence !== 'number' || isNaN(confidence) || !signals) { ok = false; reason = 'malformed_output'; }
  else if (confidence < threshold) { ok = false; reason = 'low_confidence'; }
}
return [{ json: { ...lead, ai_intent: intent, intent_confidence: confidence, extracted_signals: signals, summary, gate_passed: ok, gate_reason: reason, threshold } }];

const lead = $('Prepare AI Input').item.json;
const gate = $('Confidence & Schema Gate').item.json;
return [{ json: {
  correlation_id: lead.correlation_id,
  idempotency_key: lead.idempotency_key,
  lead_id: lead.lead_id,
  route: 'review_required',
  qualification_status: 'review_required',
  gate_reason: gate.gate_reason,
  intent: gate.ai_intent,
  intent_confidence: gate.intent_confidence,
  crm_sync_status: 'not_applicable',
  deal_eligible: false,
  deal_created: false
}}];

const lead = $('Prepare AI Input').item.json;
const gate = $('Confidence & Schema Gate').item.json;
const sig = gate.extracted_signals || {};
const known = lead.known_state || {};
let rules = $('Load Scoring Config').all().map(i => { const f = i.json.fields || i.json; return { field: f.field, operator: f.operator, expected_value: f.expected_value, points: Number(f.points) || 0, required: f.required, active: f.active }; }).filter(r => r.field && r.active !== false);
if (!rules.length) rules = [
  { field: 'budget', operator: 'exists', expected_value: '', points: 25 },
  { field: 'timeline', operator: 'exists', expected_value: '', points: 20 },
  { field: 'project_size', operator: 'exists', expected_value: '', points: 20 },
  { field: 'decision_authority', operator: 'exists', expected_value: '', points: 20 },
  { field: 'readiness', operator: 'contains', expected_value: 'ready', points: 15 }
];
const pick = (a, b) => { const av = (a == null ? '' : String(a)).trim(); const bv = (b == null ? '' : String(b)).trim(); const bad = v => !v || ['unknown','n/a','none'].includes(v.toLowerCase()); if (!bad(av)) return av; return bad(bv) ? '' : bv; };
const merged = {
  company: pick(sig.company, known.company),
  budget: pick(sig.budget, known.budget),
  timeline: pick(sig.timeline, known.timeline),
  project_size: pick(sig.project_size, known.project_size),
  decision_authority: pick(sig.decision_authority, known.decision_authority),
  readiness: pick(sig.readiness, known.readiness)
};
let score = 0;
for (const r of rules) {
  const val = merged[r.field] || '';
  let match = false;
  const exp = String(r.expected_value || '').toLowerCase();
  if (r.operator === 'exists' || r.operator === 'is_not_empty') match = !!val;
  else if (r.operator === 'equals' || r.operator === 'eq') match = val.toLowerCase() === exp;
  else if (r.operator === 'contains') match = val.toLowerCase().includes(exp);
  else if (r.operator === 'regex') { try { match = new RegExp(r.expected_value, 'i').test(val); } catch (e) {} }
  if (match) score += r.points;
}
if (score > 100) score = 100;
let temperature = 'cold';
if (score >= 70) temperature = 'hot';
else if (score >= 40) temperature = 'warm';
return [{ json: { ...gate, merged_signals: merged, score, temperature } }];

const lead = $('Prepare AI Input').item.json;
const sc = $('Compute Deterministic Score').item.json;
const intent = sc.ai_intent;
const score = sc.score;
const temperature = sc.temperature;
const rules = $('Load Routing Config').all().map(i => { const f = i.json.fields || i.json; return { condition: f.condition, owner_id: f.owner_id, notification_channel: f.notification_channel, calendar_link: f.calendar_link, active: f.active }; }).filter(r => r && r.active !== false);
let route = 'nurture';
if (intent === 'existing_customer') route = 'existing_customer';
else if (intent === 'spam_or_other') route = 'spam';
else if (intent === 'new_lead' || intent === 'follow_up') {
  if (score >= 70) route = 'qualified';
  else route = 'nurture';
}
const matchRule = rules.find(r => r.condition === route) || {};
const owner_id = matchRule.owner_id || lead.owner_hint || 'unassigned';
const notification_channel = matchRule.notification_channel || 'asana';
const calendar_link = matchRule.calendar_link || '';
const followUpDays = route === 'qualified' ? 1 : route === 'nurture' ? 7 : 0;
const followUpAt = followUpDays > 0 ? new Date(Date.now() + followUpDays * 86400000).toISOString() : null;
return [{ json: {
  correlation_id: lead.correlation_id,
  idempotency_key: lead.idempotency_key,
  lead_id: lead.lead_id,
  email: lead.email,
  name: lead.name,
  company: lead.company,
  source: lead.source,
  intent,
  intent_confidence: sc.intent_confidence,
  extracted_signals: sc.merged_signals,
  summary: sc.summary,
  score,
  temperature,
  route,
  owner_id,
  notification_channel,
  calendar_link,
  follow_up_at: followUpAt,
  deal_eligible: route === 'qualified'
}}];
